"""Verify one explicit human timing label against saved source; no engine or plots."""
from pathlib import Path
from decimal import Decimal as D
import json,hashlib,argparse
ap=argparse.ArgumentParser();ap.add_argument('--out',default=str(Path(__file__).parent));ap.add_argument('--source',default='independent-level-review/source-data-2884.json');ap.add_argument('--prior',default='interval-timing-review');a=ap.parse_args();p=Path(a.out);old=Path(a.prior)
sha=lambda b:hashlib.sha256(b).hexdigest();canon=lambda x:json.dumps(x,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode()
sr=Path(a.source).read_bytes();er=(old/'timing-evidence.json').read_bytes();pdf=(old/'output/pdf/m1-2884-recognition-timing.pdf').read_bytes()
assert sha(sr)=='ab87a51b5b8afd076603f290b10f415bd60d31ae47c5ab2f6d9d609ad4014901'
assert sha(er)=='932951965d74184a8b7e927f402a974cea6689d0998a5e874c45e027ba222e7c'
assert sha(pdf)=='16e7ad3d5b488fb497c3a5dde29730ae2df9266ad43cf65f419c8674441a7414'
s,e=json.loads(sr),json.loads(er);dec=json.loads((p/'user-decision.json').read_text());pending=json.loads((p/'resolved-timing-pending.json').read_text());f=e['frames'][0];n=f['source_records'];assert n==1207 and f['cutoff']=='2026-10-07'
seq={'bars':s['bars'][:n],'macd':s['macd'][:n],'moving_averages':{k:v[:n]for k,v in s['moving_averages'].items()}};assert 'sha256:'+sha(canon(seq))==f['source_values_fingerprint'];assert seq['bars'][-1]==f['last_bar']and seq['macd'][-1]==f['last_saved_macd'];assert all(z['date']<='2026-10-07'for z in seq['bars'])
assert f['saved_core_result_id']is None and f['saved_numeric_frame_id']is None and '2026-10-07'not in s['numeric_frame_ids']
assert dec['user_quote']=='足夠辨認了'and dec['user_time']=='2026-10-20T21:46:37+08:00'and dec['direct_prefix_labels']['2026-10-07']['sufficient']is True
assert dec['direct_prefix_labels']['2026-10-14']['sufficient']is None and all(v is None for v in dec['not_confirmed'].values())
assert dec['historical_selection_time']is None and dec['historical_signal_eligible']is False and dec['primary_pressure_id']is None
assert pending['answer_received']is True and pending['status']=='RESOLVED_USER_CONFIRMED'and pending['earlier_prefix_sufficiency']['2026-10-07']is True
ref=next(z for z in s['bars']if z['date']=='2026-09-17');assert D(f['last_bar']['close'])<D(ref['high'])and D(f['last_saved_macd']['histogram'])<0
evidence={'schema':'m1-human-prefix-positive-evidence/1','label':dec['direct_prefix_labels']['2026-10-07'],'cutoff':f['cutoff'],'source_records':n,'current_user_decision_at':dec['user_time'],'current_user_quote':dec['user_quote'],'last_original_bar':f['last_bar'],'last_original_saved_macd':f['last_saved_macd'],'source_values_fingerprint':f['source_values_fingerprint'],'prior_timing_evidence_sha256':sha(er),'unchanged_PDF_sha256':sha(pdf),'source_data_sha256':sha(sr),'saved_core_result_id':None,'saved_numeric_frame_id':None,'coexisting_raw_facts':{'close_below_Sep17_daily_high':True,'reference_bar':ref,'negative_saved_MACD_histogram':True},'finite_requirement':'This confirmed case can be described as recognizable consolidation before subsequent Oct15 rise; no universal detector or threshold inferred.','earliest_recognition_date':None,'formal_start_end_bounds_membership':None,'historical_selection_time':None,'historical_signal_eligible':False,'primary_pressure_id':None,'review_qualification':'RETROSPECTIVE_NOT_BLIND_NOT_ORIGINAL_ENGINE_OUTPUT'}
(p/'evidence.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
assert sha(Path(a.source).read_bytes())==sha(sr)and sha((old/'timing-evidence.json').read_bytes())==sha(er)and sha((old/'output/pdf/m1-2884-recognition-timing.pdf').read_bytes())==sha(pdf)
v={'schema':'m1-human-label-execution-record/1','audit_runs':1,'prior_evidence_PDF_original_source_SHAs':'PASS_EXISTING_LOCAL_VERIFIED_FILES','prefix1207_original_values_and_fingerprint':'PASS','Oct7_missing_core_and_numeric_frame_remain_null':'PASS','explicit_user_quote_scope_and_resolved_status':'PASS','Oct14_unadjudicated_and_earliest_date_formal_fields_remain_null':'PASS','close_below_reference_and_negative_MACD_preserved':'PASS_FINITE_CASE_COEXISTENCE_NOT_THRESHOLDS','source_evidence_PDF_unchanged':'PASS','new_execution':'READ_ONLY_RESEARCH_AUDIT','engine_MA_MACD_recomputations':0,'original_core_reaction_source_query_adapter_CLI_bootstrap_old_tests':'NOT_RUN','PDF_PNG_creation_or_rerender_visual_QA':'NOT_RUN_THIS_BATCH_PRIOR_VERIFIED_ARTIFACT_REUSED','browser_ZIP':'NOT_RUN','Android':'NOT_TESTED_NEW_BUILD','historical_signal_eligible':False,'primary_pressure_id':None}
(p/'verification.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'user_confirmed_cutoff':'2026-10-07','source_records':n,'pending_resolved':True,'engine_runs':0,'new_plots':0}))
